import {withStableView} from './view-stability.mjs';
import {validThesisQuote} from './thesis-online.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={read:'文献解读',answer:'原文问答',translate:'文献翻译',rewrite:'学术表达优化',ppt:'演示文稿',chart:'图表配置',diagram:'科研结构示意图',formula:'公式辅助',format:'格式建议'};
const active=item=>['queued','running'].includes(item?.status);
const outputPreview=output=>[output.text||'结构化结果已生成，采纳后可在工作区编辑。',...(Array.isArray(output.suggestions)?output.suggestions.map(s=>[s.location,s.issue,'建议：'+s.action].filter(Boolean).join('\n')):[])].join('\n\n');
export function mountToolJobPanel({container,ctx={},kind,operation,getSnapshot,onApply,onStateChange,initialState={},isCurrent=()=>true}={}){
 if(!container||typeof getSnapshot!=='function')throw Error('缺少处理区域或输入资料');
 const doc=container.ownerDocument,win=doc.defaultView;
 if(!doc.querySelector('link[data-tool-job-style]')){const link=doc.createElement('link');link.rel='stylesheet';link.href='/workspace/tool-job-panel.css';link.dataset.toolJobStyle='';doc.head.append(link);}
 let live=true,opened=false,busy=false,identity=null,quote=null,item=null,consent=false,error='',message='',auth='unknown',timer=null,state={...initialState},snapshot=state.snapshot?structuredClone(state.snapshot):null,key=state.contextKey||null;
 const controllers=new Set(),current=()=>live&&container.isConnected&&isCurrent(),same=()=>{try{return key===JSON.stringify(getSnapshot());}catch{return false;}},persist=()=>onStateChange?.({...state,snapshot,contextKey:key,itemId:item?.id||state.itemId||null,ownerId:identity?.id||state.ownerId||null});
 const stopPoll=()=>{if(timer!==null)win.clearTimeout(timer);timer=null;};
 async function api(path,data){const c=new win.AbortController();controllers.add(c);const timeout=win.setTimeout(()=>c.abort(),25000);try{
  let result;if(ctx.api)result=await ctx.api(path,data,{signal:c.signal});else{const response=await win.fetch('/api'+path,{method:data===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),signal:c.signal});result=await response.json().catch(()=>({error:'服务暂不可用'}));if(!response.ok)throw Object.assign(Error(result.error||'请求未能完成'),{status:response.status});}
  if(!current())throw Object.assign(Error('页面已切换'),{name:'AbortError'});return result;
 }catch(e){if(c.signal.aborted&&current())throw Error('连接超时，请读取原任务状态，避免重复提交。');if(/failed to fetch|fetch failed|networkerror|load failed/i.test(e.message||''))throw Error('连接暂时中断，原稿和已提交任务仍保留，请重新读取状态，避免重复提交。');throw e;}finally{win.clearTimeout(timeout);controllers.delete(c);}}
 async function owner(){auth='loading';try{const result=await api('/auth/me');if(!result.user?.id)throw Object.assign(Error('请登录账户'),{status:401});if(identity&&identity.id!==result.user.id||state.ownerId&&state.ownerId!==result.user.id){identity=null;quote=null;item=null;auth='changed';throw Error('账户已变化，请重新进入功能；原任务只属于原账户。');}identity=result.user;auth='authenticated';return identity;}catch(e){if(e.status===401){identity=null;quote=null;item=null;auth='guest';}else if(auth!=='changed')auth='error';throw e;}}
 function take(value){if(!value?.id||value.kind!==kind||value.operation!==operation||!['queued','running','completed','failed','cancelled'].includes(value.status))throw Error('任务状态不完整，请重新读取');item=value;state.itemId=item.id;persist();}
 const cost=()=>quote?.source==='credits'?`${quote.creditCost} 科研积分`:quote?.source==='membership'?'1 次会员权益':quote?.source==='bundle'?'1 次套餐权益':'本次免费';
 function render(){if(!current()||!opened)return;withStableView(container.closest('.dashboard')||container,()=>{
  container.hidden=false;const drift=key&&!same(),applied=item&&state.appliedJobId===item.id,status={queued:'正在排队',running:'正在处理',completed:'处理完成，请核对结果',failed:'处理未完成',cancelled:'已停止'};
  container.innerHTML=`<section class="tool-job-panel" aria-label="${esc(names[operation])}处理任务"><header><div><span>PAPERKNOW · AI WORKSPACE</span><h3>${esc(names[operation])}</h3></div><button type="button" class="btn secondary" data-tj-close>收起</button></header>${error?`<p class="tool-job-error" role="alert">${esc(error)}</p>`:''}<p class="tool-job-message" role="status">${esc(message)}</p>${auth==='unknown'||auth==='loading'?'<p role="status">正在确认登录状态…</p>':identity?`<p class="tool-job-meta">${esc(snapshot?.title||'当前任务')} · 仅处理本次选中的资料</p>`:auth==='guest'?`<a class="btn primary" href="/auth.html?mode=login&next=${encodeURIComponent('/workspace.html'+win.location.hash)}">登录后继续</a>`:auth==='changed'?'<p>原账户任务仍保存在原账户，当前资料可以用于新任务。</p><button type="button" class="btn secondary" data-tj-change-owner>使用当前账户新建任务</button>':'<button type="button" class="btn secondary" data-tj-auth>重新确认登录状态</button>'}${drift?'<p class="tool-job-notice">输入已有修改，原结果会保留。请重新确认当前资料后生成，避免覆盖新内容。</p>':''}${item?`<div class="tool-job-progress" role="status"><strong>${esc(status[item.status])}</strong><span>${item.completedUnits||0} / ${item.totalUnits||1} 个处理单元</span>${item.error?`<p>${esc(item.error)}</p>`:''}</div>`:''}${item?.output?`<label class="tool-job-preview-label">结果预览<textarea readonly rows="10" data-tj-preview>${esc(outputPreview(item.output))}</textarea></label>${item.output.citations?.length?`<div class="tool-job-citations"><b>原文定位</b>${item.output.citations.map(c=>`<blockquote><small>${esc(c.sourceId)}</small><p>${esc(c.quote)}</p></blockquote>`).join('')}</div>`:''}`:''}${identity&&quote&&!item?`<div class="tool-job-charge"><strong>${esc(cost())}</strong><p>确认后才开始。成功结算，失败或取消释放预占；不会自动提交下一次付费任务。</p><label><input type="checkbox" data-tj-consent ${consent?'checked':''}> 我有权使用选中的资料，同意本次 AI 处理及上述费用。</label></div>`:''}<div class="tool-job-actions">${identity&&quote&&!item?`<button type="button" class="btn primary" data-tj-start ${busy||!consent||drift?'disabled':''}>确认费用并开始</button>`:''}${item?.status==='completed'?`<button type="button" class="btn primary" data-tj-apply ${busy||drift||applied?'disabled':''}>${applied?'已采用，可继续编辑':'采用这份结果'}</button>`:''}${active(item)?`<button type="button" class="btn secondary" data-tj-refresh ${busy?'disabled':''}>读取最新状态</button><button type="button" class="btn secondary" data-tj-cancel ${busy?'disabled':''}>停止处理</button>`:identity?`<button type="button" class="btn secondary" data-tj-new ${busy?'disabled':''}>${item?'重新确认处理':'重新读取费用'}</button>`:''}${state.commandKey&&!item?`<button type="button" class="btn secondary" data-tj-recover ${busy?'disabled':''}>读取原任务状态</button>`:''}${item&&['failed','cancelled'].includes(item.status)&&item.completedUnits?`<button type="button" class="btn secondary" data-tj-resume ${busy||drift?'disabled':''}>保留已完成部分并确认继续</button>`:''}</div><p class="tool-job-footnote">原稿保留；AI 结果需要核对，不代表查重分数、学校认可或研究事实。</p></section>`;
  const $=s=>container.querySelector(s);$('[data-tj-close]').onclick=()=>{opened=false;container.hidden=true;};$('[data-tj-auth]')?.addEventListener('click',()=>void open());$('[data-tj-change-owner]')?.addEventListener('click',()=>void command(async()=>{state={};identity=null;item=null;quote=null;snapshot=null;key=null;consent=false;persist();await prepare(true);}));$('[data-tj-consent]')?.addEventListener('change',e=>{consent=e.target.checked;$('[data-tj-start]').disabled=busy||!consent||!same();});
  $('[data-tj-start]')?.addEventListener('click',()=>void command(start));$('[data-tj-new]')?.addEventListener('click',()=>void command(()=>prepare(true)));$('[data-tj-refresh]')?.addEventListener('click',()=>void command(refresh));$('[data-tj-recover]')?.addEventListener('click',()=>void command(recover));
  $('[data-tj-cancel]')?.addEventListener('click',()=>void command(async()=>{await owner();take((await api('/tool-runs/jobs/'+item.id+'/cancel',{})).item);schedule();}));
  $('[data-tj-resume]')?.addEventListener('click',()=>void command(async()=>{const resume=item.id;await prepare(true);state.resumeFromJobId=resume;persist();}));
  $('[data-tj-apply]')?.addEventListener('click',()=>void command(async()=>{await owner();if(!same())throw Error('资料已有变化，请先核对当前输入。');if(state.appliedJobId===item.id)return;const previous=state.appliedJobId;try{state.appliedJobId=item.id;persist();await onApply?.(structuredClone(item.output),item);}catch(e){state.appliedJobId=previous;try{persist();}catch{}throw e;}message='已采用，仍可继续核对、编辑与保存。';}));
 },{restoreFocus:true});}
 async function command(fn){if(busy||!current())return;busy=true;error='';render();try{await fn();}catch(e){if(current()&&e.name!=='AbortError'){if(e.status===401){identity=null;quote=null;item=null;auth='guest';}error=e.status===401?'登录后即可继续，原稿仍保留。':e.message||'操作未能完成';}}finally{busy=false;render();}}
 function schedule(){stopPoll();if(current()&&active(item))timer=win.setTimeout(()=>void command(refresh),2500);}
 async function refresh(){await owner();take((await api('/tool-runs/jobs/'+state.itemId)).item);schedule();}
 async function recover(){await owner();if(state.itemId)return refresh();if(state.commandKey){try{take((await api('/tool-runs/jobs/by-key/'+encodeURIComponent(state.commandKey))).item);schedule();}catch(e){if(e.status!==404)throw e;message='尚未找到原任务，不会自动重复提交；请重新确认费用。';}}}
 async function prepare(fresh=false){await owner();stopPoll();snapshot=structuredClone(getSnapshot());key=JSON.stringify(snapshot);item=null;quote=null;consent=false;if(fresh)state={ownerId:identity.id};state.commandKey||=win.crypto.randomUUID();persist();const cap=await api('/tool-runs/capabilities');if(!cap.ready)throw Error(cap.reason||'处理服务暂未开放');quote=await api('/tool-runs/quote',{kind,operation,snapshot});if(!validThesisQuote(quote))throw Error('费用信息不完整，请重新读取');message='请核对资料与费用后提交。';}
 async function start(){if(!quote||!consent||!same())throw Error('请先确认当前资料与费用');const agreed=quote;await owner();if(!same()||!consent||quote!==agreed||!validThesisQuote(agreed))throw Error('资料、登录状态或费用已变化，请重新确认');persist();take((await api('/tool-runs/jobs',{kind,operation,snapshot,clientKey:state.commandKey,billingToken:quote.token,consent:true,...(state.resumeFromJobId?{resumeFromJobId:state.resumeFromJobId}:{})})).item);quote=null;schedule();}
 async function open(){if(!current()||busy)return;opened=true;auth='loading';await command(async()=>{await owner();if(state.itemId||state.commandKey){await recover();if(item)return;}await prepare();});}
 function dispose(){if(!live)return;live=false;stopPoll();for(const c of controllers)c.abort();controllers.clear();}
 return{open,dispose,inputChanged(){if(!same())consent=false;render();},getState:()=>({...state,snapshot,contextKey:key,itemId:item?.id||state.itemId||null,ownerId:identity?.id||state.ownerId||null}),refresh:()=>command(refresh)};
}
